//! Vectors for LIN's verifier side, generated by `scripts/cpp_vectors/lin_vectors.cpp`.
//!
//! The test builds the same two toy shapes from the same numbers, replays every value the C++
//! tool wrote (shapes, faults, messages, layouts, rows and the binding tree) and compares it with
//! the fixture exactly.

use std::collections::HashMap;

use fp_core::chain::public::PublicBytes;
use fp_core::code::code::Code;
use fp_core::field::ext::{F, E};
use fp_core::hash::calls::HashCalls;
use fp_core::hash::modes::Digest;
use fp_core::iop::foldeq::{vector_lay, vector_room, FoldedRow, VectorLay, E_DEGREE};
use fp_core::iop::iopp::IoppStage;
use fp_core::iop::lin::{
    lin_binding_leaf, lin_binding_root, lin_binding_vertex, lin_dot_row, lin_eval_row, lin_fault,
    lin_fold_row, lin_fold_shape, lin_message_omega, lin_message_u, lin_message_w, LinBindingRoot,
    LinBindingShape, LinClaim, LinShape,
};
use fp_core::iop::message::{Reader, Writer};
use fp_core::iop::relation::{CodeId, Codes, OracleShape, Part, Unit};
use fp_core::iop::tensor::Tensor;

const VECTORS: &str = include_str!("../../fixtures/lin_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn f(s: &str) -> F {
    F(u64::from_str_radix(s, 16).unwrap())
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([f(p[0]), f(p[1]), f(p[2])])
}

fn hex(b: &[u8]) -> String {
    if b.is_empty() {
        return "-".to_string();
    }
    let mut s = String::with_capacity(2 * b.len());
    for x in b {
        s.push_str(&format!("{:02x}", x));
    }
    s
}

fn bytes(s: &str) -> Vec<u8> {
    assert_eq!(s.len() % 2, 0, "hex {}", s);
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn dhex(d: &Digest) -> String {
    let mut s = String::with_capacity(64);
    for w in d.w {
        s.push_str(&format!("{:08x}", w));
    }
    s
}

fn make_digest(seed: u32) -> Digest {
    let mut d = Digest::zero();
    for (i, w) in d.w.iter_mut().enumerate() {
        *w = seed
            .wrapping_mul(0x9E37_79B9)
            .wrapping_add((i as u32).wrapping_mul(0x85EB_CA6B));
    }
    d
}

fn salt_byte(pos: u64, k: usize) -> u8 {
    ((pos * 31 + (k as u64) * 7 + 5) & 0xFF) as u8
}

fn main_shape(name: &str, code: CodeId, rows: usize) -> OracleShape {
    let mut s = OracleShape::default();
    s.name = name.into();
    s.code = code;
    s.main_rows = rows;
    s.main_deg = E_DEGREE as u32;
    s.answers = 1;
    s
}

fn split_shape(name: &str, mask_rows: usize) -> OracleShape {
    let mut s = OracleShape::default();
    s.name = name.into();
    s.mask_rows = mask_rows;
    s.answers = 1;
    s
}

fn stages(code: CodeId) -> Vec<IoppStage> {
    vec![
        IoppStage { code, mask_code: 0, k: 2, h: 1 },
        IoppStage { code, mask_code: 0, k: 0, h: 0 },
    ]
}

fn toy_codes() -> Codes {
    let mut codes = Codes::default();
    codes.base.push(Code { log_n: 4, ell: 8, r: 1 });
    codes.base.push(Code { log_n: 4, ell: 4, r: 1 });
    codes.base.push(Code { log_n: 4, ell: 2, r: 1 });
    codes.mask.push(Code { log_n: 4, ell: 4, r: 1 });
    codes
}

/// The base shape: one code for G_u, Omega and W, so neither split is needed.
fn make_s0() -> LinShape {
    let mut s = LinShape::default();
    s.fold.index.code = Code { log_n: 4, ell: 8, r: 1 };
    s.fold.index.v = 2;
    s.fold.index.answers = 1;
    s.fold.index.salt_bytes = 40;
    s.fold.u = main_shape("G_u", 0, 2);
    s.fold.columns = 4;
    s.k_lo = 0;
    s.matrix_rows = 5;
    s.omega = main_shape("Omega", 0, 2);
    s.w = main_shape("W", 0, 2);
    s.shared_mask_code = 0;
    s.own_mask_code = 0;
    s.masks_ahead = false;
    s.test_u = stages(0);
    s.test_omega = stages(0);
    s.test_own = stages(0);
    s.test_own_omega = stages(0);
    s
}

/// The shape with both splits needed: G_u and W use code 0, Omega code 1.
fn make_s1() -> LinShape {
    let mut s = make_s0();
    s.omega = main_shape("Omega", 1, 2);
    s.shared_split = split_shape("shared split", 2);
    s.own_split = split_shape("own split", 2);
    s.masks_ahead = true;
    s.test_omega = stages(1);
    s.test_own_omega = stages(1);
    s.choice.masks_ride = true;
    s
}

fn oracle<'a>(s0: &'a LinShape, s1: &'a LinShape, name: &str) -> (&'a OracleShape, bool) {
    match name {
        "omega_S0" => (&s0.omega, s0.omega_rows_high),
        "w_S0" => (&s0.w, s0.w_rows_high),
        "u_S0" => (&s0.fold.u, s0.fold.rows_high),
        "omega_S1" => (&s1.omega, s1.omega_rows_high),
        _ => panic!("no such oracle in the fixture: {}", name),
    }
}

fn lshape(case: &str, s0: &LinShape, s1: &LinShape) -> LinShape {
    match case {
        "S0" => s0.clone(),
        "S1" => s1.clone(),
        "matrix_zero" => {
            let mut s = s0.clone();
            s.matrix_rows = 0;
            s
        }
        "k_lo_high" => {
            let mut s = s0.clone();
            s.k_lo = 31;
            s
        }
        "fold_columns" => {
            let mut s = s0.clone();
            s.fold.columns = 0;
            s
        }
        "omega_deg" => {
            let mut s = s0.clone();
            s.omega.main_deg = 1;
            s
        }
        "omega_answers" => {
            let mut s = s0.clone();
            s.omega.answers = 0;
            s
        }
        "omega_mask" => {
            let mut s = s0.clone();
            s.omega.mask_rows = 1;
            s
        }
        "matrix_fit" => {
            let mut s = s0.clone();
            s.matrix_rows = 6;
            s
        }
        "shared_leaf" => {
            let mut s = s1.clone();
            s.shared_split_leaf_class = s.omega_leaf_class;
            s
        }
        "own_leaf" => {
            let mut s = s1.clone();
            s.own_split_leaf_class = s.w_leaf_class;
            s
        }
        "split_main" => {
            let mut s = s1.clone();
            s.shared_split.main_rows = 1;
            s
        }
        "omega_code" => {
            let mut s = s1.clone();
            s.omega.code = 9;
            s
        }
        "w_code" => {
            let mut s = s1.clone();
            s.w.code = 9;
            s
        }
        "mask_code" => {
            let mut s = s0.clone();
            s.shared_mask_code = 9;
            s
        }
        "w_room" => {
            let mut s = s1.clone();
            s.w = main_shape("W", 2, 1);
            s
        }
        "u_room" => {
            let mut s = s0.clone();
            s.fold.u.main_rows = 1;
            s
        }
        _ => panic!("no such fault case: {}", case),
    }
}

#[test]
fn lin_vectors_match_the_cpp_reference() {
    let codes = toy_codes();
    let s0 = make_s0();
    let s1 = make_s1();
    let mut lines = VECTORS.lines();

    // SHAPE
    for (name, s) in [("S0", &s0), ("S1", &s1)] {
        let line = lines.next().unwrap();
        let kv = fields(line);
        assert!(line.starts_with(&format!("SHAPE {} ", name)));
        assert_eq!(kv["k_col"].parse::<u32>().unwrap(), s.k_col());
        assert_eq!(kv["k_row"].parse::<u32>().unwrap(), s.k_row());
        assert_eq!(kv["shared_split"].parse::<u32>().unwrap(), s.shared_split_needed() as u32);
        assert_eq!(kv["own_split"].parse::<u32>().unwrap(), s.own_split_needed() as u32);
        assert_eq!(kv["entries"].parse::<u64>().unwrap(), s.fold.entries());
        assert_eq!(kv["masks_ahead"].parse::<u32>().unwrap(), s.masks_ahead as u32);
        assert_eq!(kv["test_u"].parse::<usize>().unwrap(), s.test_u.len());
        assert_eq!(kv["test_omega"].parse::<usize>().unwrap(), s.test_omega.len());
        assert_eq!(kv["test_own"].parse::<usize>().unwrap(), s.test_own.len());
        assert_eq!(kv["test_own_omega"].parse::<usize>().unwrap(), s.test_own_omega.len());
    }

    // SHAPEBYTES
    for (name, s) in [("S0", &s0), ("S1", &s1)] {
        let line = lines.next().unwrap();
        let kv = fields(line);
        assert!(line.starts_with(&format!("SHAPEBYTES {} ", name)));
        let mut w = Writer::default();
        s.public_bytes(&mut w);
        assert_eq!(hex(w.bytes()), kv["bytes"], "public bytes of {}", name);
    }

    // MESSAGE
    for (name, s) in [("S0", &s0), ("S1", &s1)] {
        for tag in ["w", "u", "omega"] {
            let line = lines.next().unwrap();
            let kv = fields(line);
            assert!(line.starts_with(&format!("MESSAGE {} {} ", name, tag)));
            let m = match tag {
                "w" => lin_message_w(s),
                "u" => lin_message_u(s),
                "omega" => lin_message_omega(s),
                _ => unreachable!(),
            };
            let got: Vec<String> = m
                .iter()
                .map(|n| {
                    let mut w = Writer::default();
                    n.public_bytes(&mut w);
                    hex(w.bytes())
                })
                .collect();
            let want: Vec<String> = line
                .split_whitespace()
                .skip(4)
                .filter(|t| !t.starts_with("count=") && *t != "-")
                .map(str::to_string)
                .collect();
            assert_eq!(kv["count"].parse::<usize>().unwrap(), got.len());
            assert_eq!(got, want, "MESSAGE {} {}", name, tag);
        }
    }

    // FOLD_SHAPE
    {
        let line = lines.next().unwrap();
        let kv = fields(line);
        let f = lin_fold_shape(&s1.test_own, s1.w_leaf_class);
        assert_eq!(kv["code"].parse::<CodeId>().unwrap(), f.code);
        assert_eq!(kv["mask_code"].parse::<CodeId>().unwrap(), f.mask_code);
        assert_eq!(kv["k"].parse::<u32>().unwrap(), f.layout.k);
        assert_eq!(kv["h"].parse::<u32>().unwrap(), f.layout.h);
        assert_eq!(kv["mask_leaf_class"].parse::<u32>().unwrap(), f.mask_leaf_class);
    }

    // ROOM
    for _ in 0..4 {
        let line = lines.next().unwrap();
        let tokens: Vec<&str> = line.split_whitespace().collect();
        let kv = fields(line);
        let (o, high) = oracle(&s0, &s1, tokens[1]);
        assert_eq!(kv["rows_high"].parse::<u32>().unwrap(), high as u32);
        assert_eq!(kv["room"].parse::<u64>().unwrap(), vector_room(&codes, o, high));
    }

    // LAY
    let point = vec![
        E([F(501), F(502), F(503)]),
        E([F(502), F(503), F(504)]),
    ];
    for _ in 0..5 {
        let line = lines.next().unwrap();
        let tokens: Vec<&str> = line.split_whitespace().collect();
        let kv = fields(line);
        let (o, _) = oracle(&s0, &s1, tokens[1]);
        let high = kv["rows_high"].parse::<u32>().unwrap() != 0;
        let lay = vector_lay(&codes, o, high);
        assert_eq!(kv["row_bits"].parse::<u32>().unwrap(), lay.row_bits);
        assert_eq!(kv["place_bits"].parse::<u32>().unwrap(), lay.place_bits);
        assert_eq!(kv["bits"].parse::<u32>().unwrap(), lay.bits());

        let line = lines.next().unwrap();
        assert!(line.starts_with("INDEX"));
        for (j, tok) in line.split_whitespace().skip(1).enumerate() {
            let (a, b) = tok.split_once(':').unwrap();
            assert_eq!(a.parse::<u64>().unwrap(), j as u64);
            assert_eq!(b.parse::<u64>().unwrap(), lay.index(j as u64));
        }
        let line = lines.next().unwrap();
        assert!(line.starts_with("ENTRY"));
        for (i, tok) in line.split_whitespace().skip(1).enumerate() {
            let (a, b) = tok.split_once(':').unwrap();
            assert_eq!(a.parse::<u64>().unwrap(), i as u64);
            assert_eq!(b.parse::<u64>().unwrap(), lay.entry_at(i as u64));
        }
        let line = lines.next().unwrap();
        assert!(line.starts_with("ON_TABLE"));
        let on = lay.on_table(Tensor::eq(&point, 2, E([F(7), F(8), F(9)])));
        for (j, tok) in line.split_whitespace().skip(1).enumerate() {
            assert_eq!(on.at(j as u64), e(tok), "on_table {}", j);
        }
    }

    // The claim and the three rows.
    let gp1 = [E([F(301), F(302), F(303)]), E([F(302), F(303), F(304)]), E([F(303), F(304), F(305)])];
    let gp2 = [E([F(401), F(402), F(403)]), E([F(402), F(403), F(404)]), E([F(403), F(404), F(405)])];
    let mut claim = LinClaim::default();
    claim.g.push(Tensor::eq(&gp1, 3, E([F(11), F(12), F(13)])));
    claim.g.push(Tensor::eq(&gp2, 3, E([F(12), F(13), F(14)])));
    claim.psi = vec![E([F(101), F(102), F(103)]), E([F(102), F(103), F(104)])];
    claim.masks.push(Unit {
        oracle: 4,
        part: Part::Mask,
        index: 7,
        coeff: E([F(13), F(14), F(15)]),
    });
    claim.masks.push(Unit {
        oracle: 4,
        part: Part::Mask,
        index: 9,
        coeff: E([F(14), F(15), F(16)]),
    });
    claim.target = E([F(15), F(16), F(17)]);
    let zeta = vec![E([F(201), F(202), F(203)]), E([F(202), F(203), F(204)]), E([F(203), F(204), F(205)])];

    let omega_lay = vector_lay(&codes, &s0.omega, s0.omega_rows_high);
    let w_lay = vector_lay(&codes, &s0.w, s0.w_rows_high);
    let u_lay = vector_lay(&codes, &s0.fold.u, s0.fold.rows_high);
    let u = FoldedRow { oracle: 3, lay: u_lay };

    for tag in ["eval", "fold", "dot"] {
        let line = lines.next().unwrap();
        let (got_tag, rest) = line["ROW ".len()..].split_once(' ').unwrap();
        assert_eq!(got_tag, tag);
        let name = rest.strip_prefix("name=").unwrap().split(" target=").next().unwrap();
        let target = e(line.split(" target=").nth(1).unwrap());
        let row = match tag {
            "eval" => lin_eval_row(&s0, &claim, 1, w_lay),
            "fold" => lin_fold_row(&s0, &claim.psi, &zeta, &u, 2, omega_lay),
            "dot" => lin_dot_row(&s0, &claim.g, &claim.psi, 2, omega_lay, 1, w_lay),
            _ => unreachable!(),
        };
        assert_eq!(row.name, name);
        assert_eq!(row.target, target);

        let line = lines.next().unwrap();
        assert!(line.starts_with("UNIT"));
        let toks: Vec<&str> = line["UNIT".len()..].split_whitespace().collect();
        assert_eq!(toks.len(), row.units.len(), "UNIT count of {}", tag);
        for (tok, unit) in toks.iter().zip(row.units.iter()) {
            let p: Vec<&str> = tok.splitn(4, ':').collect();
            assert_eq!(p.len(), 4, "unit {}", tok);
            assert_eq!(p[0].parse::<u32>().unwrap(), unit.oracle);
            assert_eq!(p[1].parse::<u32>().unwrap(), unit.part as u32);
            assert_eq!(p[2].parse::<u64>().unwrap(), unit.index);
            assert_eq!(e(p[3]), unit.coeff);
        }

        let coef_count = match tag {
            "eval" => 1,
            _ => 2,
        };
        for _ in 0..coef_count {
            let line = lines.next().unwrap();
            let (o_s, vals) = line["COEF o=".len()..].split_once(' ').unwrap();
            let o: u32 = o_s.parse().unwrap();
            let want: Vec<E> = vals.split_whitespace().map(e).collect();
            let lay: VectorLay = match o {
                1 => w_lay,
                2 => omega_lay,
                3 => u_lay,
                _ => panic!("no such coefficient oracle: {}", o),
            };
            assert_eq!(want.len() as u32, 1u32 << lay.bits(), "COEF o={} count", o);
            for (j, v) in want.iter().enumerate() {
                assert_eq!(row.coefficient(o, Part::Main, j as u64), *v, "coef o={} j={}", o, j);
            }
        }
    }

    // FAULT
    for _ in 0..17 {
        let line = lines.next().unwrap();
        let rest = line.strip_prefix("FAULT ").unwrap();
        let (case, fault) = rest.split_once(' ').unwrap();
        let s = lshape(case, &s0, &s1);
        let want = fault.strip_prefix("fault=").unwrap();
        assert_eq!(lin_fault(&codes, &s).unwrap_or("NULL"), want, "FAULT {}", case);
    }

    // BINDING_SHAPE
    let bs = LinBindingShape { log_leaves: 3, salt_bytes: 40 };
    let line = lines.next().unwrap();
    let kv = fields(line);
    assert_eq!(kv["log_leaves"].parse::<u32>().unwrap(), bs.log_leaves);
    assert_eq!(kv["salt_bytes"].parse::<usize>().unwrap(), bs.salt_bytes);
    assert_eq!(bs.public_fault().unwrap_or("NULL"), kv["fault"]);
    {
        let mut w = Writer::default();
        bs.public_bytes(&mut w);
        assert_eq!(hex(w.bytes()), kv["bytes"]);
    }

    // BINDING_FAULT
    for _ in 0..2 {
        let line = lines.next().unwrap();
        let (case, fault) = line.strip_prefix("BINDING_FAULT ").unwrap().split_once('=').unwrap();
        let s = match case {
            "deep" => LinBindingShape { log_leaves: 49, salt_bytes: 40 },
            "salt" => LinBindingShape { log_leaves: 3, salt_bytes: 39 },
            _ => panic!("no such binding fault: {}", case),
        };
        assert_eq!(s.public_fault().unwrap(), fault);
    }

    // VERTEX
    let configuration = make_digest(1);
    let seal = make_digest(2);
    {
        let line = lines.next().unwrap();
        let kv = fields(line);
        let left = make_digest(51);
        let right = make_digest(52);
        assert_eq!(dhex(&left), kv["left"]);
        assert_eq!(dhex(&right), kv["right"]);
        let got = lin_binding_vertex(&configuration, &left, &right, &mut HashCalls::new());
        assert_eq!(dhex(&got), kv["digest"]);
    }

    // LEAF
    let salt: Vec<u8> = (0..bs.salt_bytes).map(|k| salt_byte(5, k)).collect();
    {
        let line = lines.next().unwrap();
        let kv = fields(line);
        assert_eq!(kv["place"].parse::<u64>().unwrap(), 5);
        assert_eq!(hex(&salt), kv["salt"]);
        let got = lin_binding_leaf(&bs, &configuration, 5, &seal, &salt, &mut HashCalls::new());
        assert_eq!(dhex(&got), kv["digest"]);
    }

    // PATH and ROOT
    let sib3 = make_digest(41);
    let sib2 = make_digest(42);
    let sib1 = make_digest(43);
    let line = lines.next().unwrap();
    let kv = fields(line);
    {
        let mut w = Writer::default();
        w.put_u64(5);
        w.put_bytes(&salt);
        w.put_digest(&sib3);
        w.put_digest(&sib2);
        w.put_digest(&sib1);
        assert_eq!(hex(w.bytes()), kv["bytes"]);
        assert_eq!(dhex(&sib3), kv["sib3"]);
        assert_eq!(dhex(&sib2), kv["sib2"]);
        assert_eq!(dhex(&sib1), kv["sib1"]);

        let path = bytes(kv["bytes"]);
        let mut r = Reader::new(&path);
        let mut out = LinBindingRoot::default();
        let ok = lin_binding_root(&mut r, &bs, &configuration, &seal, &mut out, &mut HashCalls::new());
        let line = lines.next().unwrap();
        let kv = fields(line);
        assert_eq!(ok as u32, kv["ok"].parse::<u32>().unwrap());
        assert_eq!(r.at_end() as u32, kv["at_end"].parse::<u32>().unwrap());
        assert_eq!(out.places(), kv["places"].parse::<u64>().unwrap());
        assert_eq!(dhex(out.digest()), kv["digest"]);
    }

    // ROOT_BAD: a place out of range, then a path short of siblings.
    {
        let line = lines.next().unwrap();
        let kv = fields(line);
        let mut w = Writer::default();
        w.put_u64(8);
        w.put_bytes(&salt);
        w.put_digest(&sib3);
        let mut r = Reader::new(w.bytes());
        let mut out = LinBindingRoot::default();
        let ok = lin_binding_root(&mut r, &bs, &configuration, &seal, &mut out, &mut HashCalls::new());
        assert_eq!(ok as u32, kv["ok"].parse::<u32>().unwrap());
    }
    {
        let line = lines.next().unwrap();
        let kv = fields(line);
        assert!(line.starts_with("ROOT_BAD short "));
        let mut w = Writer::default();
        w.put_u64(5);
        w.put_bytes(&salt);
        let mut r = Reader::new(w.bytes());
        let mut out = LinBindingRoot::default();
        let ok = lin_binding_root(&mut r, &bs, &configuration, &seal, &mut out, &mut HashCalls::new());
        assert_eq!(ok as u32, kv["ok"].parse::<u32>().unwrap());
    }

    // PATH0 and ROOT0: the tree of one leaf has no siblings.
    {
        let one = LinBindingShape { log_leaves: 0, salt_bytes: 40 };
        let salt0: Vec<u8> = (0..one.salt_bytes).map(|k| salt_byte(0, k)).collect();
        let line = lines.next().unwrap();
        let kv = fields(line);
        let mut w = Writer::default();
        w.put_u64(0);
        w.put_bytes(&salt0);
        assert_eq!(hex(w.bytes()), kv["bytes"]);

        let path = bytes(kv["bytes"]);
        let mut r = Reader::new(&path);
        let mut out = LinBindingRoot::default();
        let ok = lin_binding_root(&mut r, &one, &configuration, &seal, &mut out, &mut HashCalls::new());
        let line = lines.next().unwrap();
        let kv = fields(line);
        assert_eq!(ok as u32, kv["ok"].parse::<u32>().unwrap());
        assert_eq!(out.places(), kv["places"].parse::<u64>().unwrap());
        assert_eq!(dhex(out.digest()), kv["digest"]);
    }

    // MADE_UP
    {
        let line = lines.next().unwrap();
        let kv = fields(line);
        let root = LinBindingRoot::made_up_without_a_tree(make_digest(77), 6);
        assert_eq!(root.places(), kv["places"].parse::<u64>().unwrap());
        assert_eq!(dhex(root.digest()), kv["digest"]);
    }

    assert!(lines.next().is_none());
}
